// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "OK it looks good, now implement it. you can use subagents for the different parts of the implemetation. After the implemetation deploy it." (plan: reduced LL table + step-by-step simulation)
// Changes: LL parse simulation panel – step controls with autoplay, reduced LL table highlighting the current
//          lookup, stack and input chips, the applied rule, left parse so far and the clickable full trace.
// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Now i want this change. the LL tab should be split into two, rather it should have 2 modes:\n- simulation\n- viewer"
// Changes: Now the whole "Simulácia" mode of the LL tab (own resizable two-column layout).

import { useCallback, useEffect, useId, useMemo, useRef, useState, type KeyboardEvent } from 'react'
import type { LLSimState } from '#/lib/project'
// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: Visited-cell keys come from the grammar module (llCellKey) instead of a hand-typed separator.
import { EOF, endMarker, llCellKey, reducedTable, simulateLL, type LLAnalysis } from '#/lib/grammar'
// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: Step keys are scoped to the simulation columns and only take unclaimed presses (simKeys); the input has a
//          visible label and described help; the reduced table is the shared LLGrid over llTableModel (detail line
//          instead of title tooltips); trace rows are reachable buttons with aria-current="step"; current/used cells,
//          the stack top and the current token are marked by outline/text too (visible in forced colours); contrast.
import { llTableModel } from '#/lib/tableModel'
import { Button, Help, Label, Panel, ResultLine, Segmented, TextInput, cx } from './ui'
import { LLGrid } from './LLGrid'
import { pickTableModel } from './llGrid'
import { ARROW_CONSUMERS, simStep } from './simKeys'
import { SplitLayout } from './SplitLayout'

const SPEEDS = [
  { label: '0,5×', ms: 1200 },
  { label: '1×', ms: 600 },
  { label: '2×', ms: 300 },
  { label: '4×', ms: 120 },
]

const chip = 'rounded-md border px-1.5 py-0.5 font-mono text-[12px] whitespace-nowrap'
// Current element (stack top, input token, looked-up cell): an outline survives forced colours, a ring (box-shadow) does not.
const currentOutline = 'outline-2 outline-offset-1 outline-indigo-300'

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "also make sure that the simulation input and state is also saved in the DB"
// Changes: Step and speed live in the project data (saved to the DB) instead of local state; play/pause stays local.
export function LLSimulation({
  a,
  input,
  onInput,
  state,
  onState,
}: {
  a: LLAnalysis | null
  input: string
  onInput: (value: string) => void
  state: LLSimState
  onState: (fn: (prev: LLSimState) => LLSimState) => void
}) {
  const sim = useMemo(() => (a ? simulateLL(a, input) : null), [a, input])
  const reduced = useMemo(() => (a && sim ? reducedTable(a, sim.rows) : null), [a, sim])
  const reducedModel = useMemo(() => (a && reduced ? pickTableModel(llTableModel(a), reduced.N, reduced.cols) : null), [a, reduced])
  const inputId = useId()
  const inputHelpId = useId()
  const [playing, setPlaying] = useState(false)

  const last = sim ? sim.rows.length - 1 : 0
  // The saved step may point past the end when the grammar changed elsewhere – clamp it.
  const step = Math.min(state.step, last)
  const speed = Math.min(state.speed, SPEEDS.length - 1)
  const setStep = useCallback(
    (v: number | ((s: number) => number)) =>
      onState((prev) => {
        const next = typeof v === 'function' ? v(Math.min(prev.step, last)) : v
        return next === prev.step ? prev : { ...prev, step: next }
      }),
    [onState, last],
  )
  const setSpeed = (i: number) => onState((prev) => ({ ...prev, speed: i }))

  // A new input or grammar starts from the beginning (a failing run jumps straight to the error). The first run is
  // skipped so the step restored from the DB is kept when the tab is opened.
  const restored = useRef(true)
  useEffect(() => {
    setPlaying(false)
    if (restored.current) {
      restored.current = false
      return
    }
    setStep(sim && !sim.ok ? sim.rows.length - 1 : 0)
  }, [sim])

  useEffect(() => {
    if (!playing) return
    if (step >= last) {
      setPlaying(false)
      return
    }
    const t = setTimeout(() => setStep((s) => Math.min(s + 1, last)), SPEEDS[speed].ms)
    return () => clearTimeout(t)
  }, [playing, step, last, speed])

  // Keeps the looked-up cell visible inside the reduced table's own scroll box (the page itself does not move).
  const tableBox = useRef<HTMLDivElement>(null)
  useEffect(() => {
    const box = tableBox.current
    const td = box?.querySelector<HTMLElement>('[data-current]')
    if (!box || !td) return
    const b = box.getBoundingClientRect()
    const c = td.getBoundingClientRect()
    const head = box.querySelector('thead')?.getBoundingClientRect().height ?? 0
    const side = box.querySelector('tbody th')?.getBoundingClientRect().width ?? 0
    if (c.left < b.left + side) box.scrollLeft -= b.left + side - c.left + 8
    else if (c.right > b.right) box.scrollLeft += c.right - b.right + 8
    if (c.top < b.top + head) box.scrollTop -= b.top + head - c.top + 8
    else if (c.bottom > b.bottom) box.scrollTop += c.bottom - b.bottom + 8
  }, [step, sim])

  const go = (s: number) => {
    setPlaying(false)
    setStep(Math.max(0, Math.min(last, s)))
  }

  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
  // Changes: Was a window listener that took ← → Home End from every element (the split separator, radios…).
  //          Now attached to the two simulation columns only and ignores presses already handled or aimed at a
  //          control that uses arrows itself (ARROW_CONSUMERS); at either end of the run the key stays native.
  const onStepKey = (e: KeyboardEvent<HTMLDivElement>) => {
    const target = e.nativeEvent.composedPath()[0]
    const consumesArrows = target instanceof Element && target.matches(ARROW_CONSUMERS)
    const next = simStep(e, { consumesArrows }, step, last)
    if (next === null) return
    e.preventDefault()
    go(next)
  }

  const cur = sim?.rows[Math.min(step, last)]
  const prev = sim && step > 0 ? sim.rows[step - 1] : undefined
  const pushedFrom = cur && prev?.kind === 'expand' ? cur.stackSyms.length - (prev.pushed ?? 0) : Infinity
  const usedCells = useMemo(
    () => new Set((sim?.rows.slice(0, step) ?? []).flatMap((r) => (r.cell ? [llCellKey(...r.cell)] : []))),
    [sim, step],
  )
  const parse = (sim?.rows.slice(0, step + 1) ?? []).flatMap((r) => (r.rule ? [r.rule] : []))
  const look = cur && sim ? (sim.input[cur.pos] ?? EOF) : ''
  const topRow = cur?.cell?.[0] ?? (a && cur && a.N.includes(cur.stackSyms[cur.stackSyms.length - 1]) ? cur.stackSyms[cur.stackSyms.length - 1] : '')

  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "Now i want this change. the LL tab should be split into two, rather it should have 2 modes:\n- simulation\n- viewer"
  // Changes: Simulation mode layout – left: input, controls and current state; right: reduced LL table and the full trace.
  const ready = sim && cur && a && reduced
  return (
    <SplitLayout id="ll-sim" fill>
      <div className="min-w-0" onKeyDown={onStepKey}>
        <Panel title="Simulácia LL analýzy">
          <Label htmlFor={inputId}>Vstupný reťazec</Label>
          <TextInput id={inputId} value={input} placeholder="i + i * i" onChange={(e) => onInput(e.target.value)} aria-describedby={inputHelpId} />
          <div id={inputHelpId}>
            <Help>
              Tokeny oddelené medzerou, <code>{a ? endMarker(a) : EOF}</code> sa pridá automaticky, ak chýba. Pri konflikte sa použije prvé pravidlo v
              bunke. Krokovať sa dá aj šípkami ← → (Home/End), keď je fokus v simulácii mimo poľa, posuvníka a tabuľky.
            </Help>
          </div>
          {ready && (
            <div className="mt-3 grid grid-cols-[minmax(0,1fr)] gap-3">
              <div className="flex flex-wrap items-center gap-2">
                <Button onClick={() => go(0)} disabled={step === 0} aria-label="Prvý krok">⏮</Button>
                <Button onClick={() => go(step - 1)} disabled={step === 0} aria-label="Predchádzajúci krok">◀</Button>
                <Button
                  onClick={() => {
                    if (step >= last) setStep(0)
                    setPlaying((p) => !p)
                  }}
                  aria-label={playing ? 'Pozastaviť' : 'Prehrať'}
                >
                  {playing ? '⏸' : '▶︎ Prehrať'}
                </Button>
                <Button onClick={() => go(step + 1)} disabled={step >= last} aria-label="Ďalší krok">▶</Button>
                <Button onClick={() => go(last)} disabled={step >= last} aria-label="Posledný krok">⏭</Button>
                {/* AI generated by: Claude Code / claude-opus-5-5
                    Prompt: "the sim speed selector have a weird selector could you look into that"
                    Changes: Segmented pill control (shared with the LL mode switch) instead of a native <select>. */}
                <Segmented label="Rýchlosť prehrávania" size="sm" value={speed} onChange={setSpeed} options={SPEEDS.map((sp, i) => ({ value: i, label: sp.label }))} />
                <span className="ml-auto text-xs text-zinc-400 tabular-nums">
                  Krok {step + 1} / {last + 1}
                </span>
              </div>
              <input
                type="range"
                min={0}
                max={last}
                value={step}
                onChange={(e) => go(Number(e.target.value))}
                aria-label="Krok simulácie"
                aria-valuetext={`Krok ${step + 1} z ${last + 1}`}
                className="w-full accent-indigo-400"
              />

              <div className="grid grid-cols-[auto_minmax(0,1fr)] items-start gap-x-3 gap-y-2 text-[13px]">
                {/* Newly pushed symbols: amber + dashed border; top: outline (both visible without colour / in forced colours). */}
                <span className="pt-0.5 text-xs text-zinc-400">Zásobník</span>
                <div className="flex flex-wrap gap-1">
                  {cur.stackSyms.length === 0 && <span className="text-zinc-400">ε</span>}
                  {cur.stackSyms.map((s, i) => {
                    const top = i === cur.stackSyms.length - 1
                    const pushed = i >= pushedFrom
                    return (
                      <span
                        key={i}
                        className={cx(
                          chip,
                          pushed ? 'border-dashed border-amber-300/60 bg-amber-400/15 text-amber-100' : 'border-white/10 bg-white/5 text-zinc-200',
                          top && currentOutline,
                          top && (cur.kind === 'expand' || cur.kind === 'match') && 'line-through decoration-indigo-300',
                        )}
                      >
                        {s}
                        {(top || pushed) && <span className="sr-only"> ({[top && 'vrchol', pushed && 'práve vložený'].filter(Boolean).join(', ')})</span>}
                      </span>
                    )
                  })}
                  <span aria-hidden="true" className="self-center text-[11px] text-zinc-400">
                    ← vrchol
                  </span>
                </div>

                <span className="pt-0.5 text-xs text-zinc-400">Vstup</span>
                <div className="flex flex-wrap gap-1">
                  {sim.input.map((t, i) => (
                    <span
                      key={i}
                      className={cx(
                        chip,
                        i < cur.pos && 'border-transparent text-zinc-400 line-through decoration-zinc-500',
                        i === cur.pos && cx('border-indigo-300/50 bg-indigo-500/25 text-indigo-100', currentOutline),
                        i > cur.pos && 'border-white/10 bg-white/5 text-zinc-200',
                      )}
                    >
                      {t}
                      {i < cur.pos && <span className="sr-only"> (prečítaný)</span>}
                      {i === cur.pos && <span className="sr-only"> (aktuálny token)</span>}
                    </span>
                  ))}
                </div>

                <span className="pt-0.5 text-xs text-zinc-400">Akcia</span>
                <div
                  className={cx(
                    'font-mono break-words',
                    cur.kind === 'expand' && 'text-indigo-200',
                    cur.kind === 'match' && 'text-zinc-200',
                    cur.kind === 'accept' && 'text-emerald-300',
                    cur.kind === 'error' && 'text-rose-300',
                  )}
                >
                  {cur.kind === 'expand' && cur.cell ? `[${cur.cell[0]}, ${cur.cell[1]}] → ` : ''}
                  {cur.kind === 'error' ? `chyba – ${sim.message}` : cur.action}
                </div>

                <span className="pt-0.5 text-xs text-zinc-400">Rozbor</span>
                <div className="font-mono break-words text-zinc-400">
                  {parse.length === 0 && '–'}
                  {parse.map((n, i) => (
                    <span key={i} className={cx(i === parse.length - 1 && cur.kind === 'expand' && 'font-bold text-amber-200')}>
                      {i > 0 && ' '}
                      {n}
                    </span>
                  ))}
                </div>
              </div>

              {step === last && <ResultLine ok={sim.ok}>{sim.ok ? sim.message : `Chyba: ${sim.message}`}</ResultLine>}

            </div>
          )}
        </Panel>
      </div>
      <div className="min-w-0" onKeyDown={onStepKey}>
        {ready && reducedModel ? (
          <>
            <Panel
              title={
                <>
                  Redukovaná LL tabuľka{' '}
                  <span className="font-normal text-zinc-400">
                    ({reduced.N.length} × {reduced.cols.length} z {a.N.length} × {a.cols.length})
                  </span>
                </>
              }
            >
              {reduced.N.length > 0 ? (
                <>
                  <Help>
                    Aktuálna bunka má plný rámik, už použité bunky prerušovaný rámik a značku ✓. Šípky medzi bunkami nekrokujú simuláciu.
                  </Help>
                  <div className="mt-2">
                    <LLGrid
                      model={reducedModel}
                      caption="Redukovaná LL tabuľka"
                      sticky
                      boxRef={tableBox}
                      boxClassName="max-h-[70vh]"
                      className="text-[12px]"
                      idleCell={cur.cell ? { row: reduced.N.indexOf(cur.cell[0]), col: reduced.cols.indexOf(cur.cell[1]) } : null}
                      headClass={(sym, axis) => ((axis === 'row' ? sym === topRow : sym === look) ? 'bg-indigo-950! text-indigo-100! underline decoration-2 underline-offset-2' : undefined)}
                      mark={(A, c, cell) => {
                        const isCur = cur.cell?.[0] === A && cur.cell[1] === c
                        // Exactly one look per cell: current lookup > already used > on the current row/column > idle.
                        if (isCur)
                          return {
                            current: true,
                            text: '∅',
                            note: 'aktuálna bunka',
                            className: cell.text
                              ? 'bg-indigo-500/40 font-bold text-white outline-2 -outline-offset-2 outline-indigo-200'
                              : 'bg-rose-500/40 font-bold text-rose-100 outline-2 -outline-offset-2 outline-rose-200',
                          }
                        if (usedCells.has(llCellKey(A, c)))
                          return { note: 'použitá', className: "bg-emerald-500/15 text-emerald-200 outline-1 -outline-offset-3 outline-dashed outline-emerald-300/70 after:ml-0.5 after:text-[10px] after:content-['✓'_/_'']" }
                        if (A === topRow || c === look) return { className: cx('bg-indigo-500/10', cell.text ? 'text-indigo-200' : 'text-zinc-400') }
                        return undefined
                      }}
                    />
                  </div>
                </>
              ) : (
                <Help>Simulácia nepoužila žiadnu bunku tabuľky.</Help>
              )}
            </Panel>
            <Panel title={`Celý priebeh (${last + 1} krokov)`}>
              <Help>Tlačidlo s číslom kroku prejde na daný krok; aktuálny krok má značku ▸.</Help>
              <div role="region" tabIndex={0} aria-label="Celý priebeh simulácie" className="mt-2 max-h-[70vh] overflow-auto">
                <table className="w-full border-collapse text-[12px]">
                  <caption className="sr-only">Celý priebeh simulácie, {last + 1} krokov</caption>
                  <thead>
                    <tr>
                      {['#', 'Zásobník', 'Vstup', 'Akcia'].map((h) => (
                        <th key={h} scope="col" className="sticky top-0 border-b border-white/10 bg-zinc-900 px-2 py-1.5 text-left text-xs font-semibold text-zinc-400">
                          {h}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody className="font-mono">
                    {sim.rows.map((r, i) => {
                      const current = i === step
                      return (
                        <tr key={i} onClick={() => go(i)} className={cx('cursor-pointer hover:bg-white/5', current && 'bg-indigo-500/20 text-indigo-100 outline-1 -outline-offset-1 outline-indigo-300/70')}>
                          <th scope="row" className="border-b border-white/5 p-0 text-left font-normal">
                            <button
                              type="button"
                              aria-current={current ? 'step' : undefined}
                              onClick={(e) => {
                                e.stopPropagation()
                                go(i)
                              }}
                              className={cx(
                                'w-full min-w-11 rounded px-2 py-1 text-left tabular-nums focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-indigo-400',
                                current ? 'font-bold text-indigo-100' : 'text-zinc-400',
                              )}
                            >
                              <span aria-hidden="true" className="inline-block w-3">
                                {current ? '▸' : ''}
                              </span>
                              <span className="sr-only">Krok </span>
                              {i + 1}
                            </button>
                          </th>
                          <td className="border-b border-white/5 px-2 py-1 whitespace-nowrap">{r.stack}</td>
                          <td className="border-b border-white/5 px-2 py-1 whitespace-nowrap">{r.input}</td>
                          <td className={cx('border-b border-white/5 px-2 py-1 whitespace-nowrap', !current && 'text-zinc-400')}>{r.action}</td>
                        </tr>
                      )
                    })}
                  </tbody>
                </table>
              </div>
            </Panel>
          </>
        ) : (
          <Panel title="Redukovaná LL tabuľka">
            <Help>{a ? 'Zadaj vstup vľavo – zobrazí sa tu časť LL tabuľky, ktorú simulácia použije, a celý priebeh.' : 'Gramatika nie je k dispozícii.'}</Help>
          </Panel>
        )}
      </div>
    </SplitLayout>
  )
}
